  <li><b>\u05E1\u05E7\u05E8\u05D9\u05E4\u05D8 \u203A \u05E1\u05D9\u05DE\u05E0\u05D9\u05D5\u05EA PDF</b>: \u05E2\u05E8\u05D9\u05DB\u05EA \u05D4\u05DE\u05E4\u05EA\u05D7\u05D5\u05EA \u05E9\u05DC Tag PDF \u05D1\u05E7\u05D5\u05D1\u05E5 \u05D4\u05E1\u05D2\u05E0\u05D5\u05DF \u05D1\u05E9\u05D5\u05E8\u05D5\u05EA, \u05E2\u05DD \u05D4\u05D5\u05E1\u05E4\u05D4.</li>
